/**
 * Writes scripts/check-schema.sql from scripts/schema.expected.txt.
 *
 * The point of the generated file is that it needs no connection string and
 * no Node: it is pasted into the Neon SQL editor and reports which columns
 * the collections describe but the deployed database does not have. Those are
 * exactly the columns whose absence makes an admin screen render blank or an
 * upload return "Something went wrong".
 *
 *   node scripts/generate-schema-check.mjs
 */
import { readFileSync, writeFileSync } from "node:fs";

const rows = readFileSync(new URL("./schema.expected.txt", import.meta.url), "utf8")
  .split("\n")
  .map((line) => line.trim())
  .filter(Boolean)
  // The file also lists the enum types, as `ENUM name = a,b,c`. Those are not
  // columns and information_schema.columns knows nothing about them.
  .filter((line) => !line.startsWith("ENUM "))
  .map((line) => {
    const [qualified] = line.split(/\s+/);
    const dot = qualified.indexOf(".");
    return [qualified.slice(0, dot), qualified.slice(dot + 1)];
  })
  .filter(([table, column]) => table && column);

const values = rows.map(([t, c]) => `  ('${t}', '${c}')`).join(",\n");

writeFileSync(
  new URL("./check-schema.sql", import.meta.url),
  `-- Which columns do the collections describe that the database does not have?
--
-- Read-only. Paste into the Neon SQL editor (or any psql) and run. Every row
-- that comes back is a column Payload will try to select and Postgres will
-- reject — which is what makes an admin screen render blank, a listing come
-- back empty, or an upload return "Something went wrong".
--
-- No rows means the deployed schema matches what the collections describe.
--
-- Generated by scripts/generate-schema-check.mjs from schema.expected.txt.
-- Do not edit by hand; regenerate it.

WITH expected(table_name, column_name) AS (VALUES
${values}
)
SELECT
  e.table_name AS missing_from_table,
  e.column_name AS missing_column
FROM expected e
LEFT JOIN information_schema.columns c
  ON c.table_schema = 'public'
 AND c.table_name = e.table_name
 AND c.column_name = e.column_name
WHERE c.column_name IS NULL
ORDER BY 1, 2;
`,
);

console.log(`check-schema.sql written — ${rows.length} expected columns.`);
